using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var researchTools = new ResearchTools();

// --- Build the agent ---------------------------------------------------------

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools =
            [
                AIFunctionFactory.Create(researchTools.SearchWeb),
                AIFunctionFactory.Create(researchTools.SaveNote),
                AIFunctionFactory.Create(researchTools.GetNotes),
            ],
        },
    });

// --- Run the agent -----------------------------------------------------------

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    var prompt = $"""
        Research the following topic: "{topic}"

        Follow these steps:
        1. Search the web for information about the topic using multiple relevant queries.
        2. Save important findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieve all notes using GetNotes.
        4. Provide a comprehensive summary of your findings, citing the sources.

        Be thorough but concise. Use at least 2 different search queries to get broad coverage.
        """;

    Console.WriteLine($"\nResearching: {topic}\n");

    var session = await agent.CreateSessionAsync();

    await foreach (var update in agent.RunStreamingAsync(prompt, session))
    {
        Console.Write(update.Text);
    }

    Console.WriteLine("\n");
}

Console.WriteLine("Goodbye!");

// --- Tool implementations ----------------------------------------------------

public sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new();
    private readonly List<string> _notes = [];

    [Description("Search the web for information about a query. Returns a list of search results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var response = await s_httpClient.GetFromJsonAsync<JsonElement>(url, cancellationToken);

            var results = new List<string>();

            // Extract the abstract if available
            var abstractText = response.GetProperty("AbstractText").GetString();
            var abstractSource = response.GetProperty("AbstractSource").GetString();
            var abstractUrl = response.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"Source: {abstractSource}\nURL: {abstractUrl}\nSummary: {abstractText}");
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"URL: {firstUrl}\nInfo: {text}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for \"{query}\". Try a different search query.";
            }

            return $"Search results for \"{query}\":\n\n" + string.Join("\n---\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The content of the note including key facts and source URLs")] string content)
    {
        var note = $"## {title}\n{content}";
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieve all saved research notes to review before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return $"Saved notes ({_notes.Count}):\n\n" + string.Join("\n\n", _notes);
    }

    public void ClearNotes() => _notes.Clear();
}

